exports.init = (params, rng) => {
  const w = 32;
  const h = 32;
  const bg = params.backgroundTemp ?? 0;
  const hot = params.hotSpotTemp ?? 100;
  const grid = [];
  for (let y=0; y<h; y++) {
    const row = [];
    for (let x=0; x<w; x++) row.push(bg);
    grid.push(row);
  }
  const cx = w/2 - 0.5;
  const cy = h/2 - 0.5;
  const r = 4;
  for (let y=0; y<h; y++) {
    for (let x=0; x<w; x++) {
      const dx = x - cx;
      const dy = y - cy;
      const d2 = dx*dx + dy*dy;
      if (d2 <= r*r) {
        grid[y][x] = hot;
      } else if (d2 <= (r+1)*(r+1)) {
        const d = Math.sqrt(d2);
        const t = d - r;
        grid[y][x] = bg + (hot - bg) * (1 - t);
      }
    }
  }
  return { w, h, grid };
};
exports.step = (state, params, rng) => {
  const w = state.w;
  const h = state.h;
  const alpha = params.diffusivity ?? 0.1;
  const bg = params.backgroundTemp ?? 0;
  const insulated = params.insulated ?? true;
  const grid = state.grid;
  const newGrid = [];
  for (let y=0; y<h; y++) {
    const newRow = [];
    for (let x=0; x<w; x++) {
      const c = grid[y][x];
      if (alpha === 0) { newRow.push(c); continue; }
      let left, right, up, down;
      if (insulated) {
        left = x>0 ? grid[y][x-1] : grid[y][x];
        right = x<w-1 ? grid[y][x+1] : grid[y][x];
        up = y>0 ? grid[y-1][x] : grid[y][x];
        down = y<h-1 ? grid[y+1][x] : grid[y][x];
      } else {
        left = x>0 ? grid[y][x-1] : bg;
        right = x<w-1 ? grid[y][x+1] : bg;
        up = y>0 ? grid[y-1][x] : bg;
        down = y<h-1 ? grid[y+1][x] : bg;
      }
      const lap = left + right + up + down - 4*c;
      let nv = c + alpha * lap;
      if (nv < 0) nv = 0;
      if (nv > 100) nv = 100;
      newRow.push(nv);
    }
    newGrid.push(newRow);
  }
  if (!insulated) {
    for (let x=0; x<w; x++) { newGrid[0][x] = bg; newGrid[h-1][x] = bg; }
    for (let y=0; y<h; y++) { newGrid[y][0] = bg; newGrid[y][w-1] = bg; }
  }
  return { w, h, grid: newGrid };
};
exports.observe = (state, params) => {
  const w = state.w;
  const h = state.h;
  const grid = state.grid;
  const N = w*h;
  let sum = 0;
  let max = -Infinity;
  for (let y=0; y<h; y++) for (let x=0; x<w; x++) { const v=grid[y][x]; sum+=v; if(v>max) max=v; }
  const mean = sum / N;
  let varSum = 0;
  for (let y=0; y<h; y++) for (let x=0; x<w; x++) { const d=grid[y][x]-mean; varSum+=d*d; }
  const tempVariance = Math.sqrt(varSum / N);
  let fluxSum = 0;
  let cnt = 0;
  for (let y=1; y<h-1; y++) for (let x=1; x<w-1; x++) {
    const dx = (grid[y][x+1] - grid[y][x-1]) * 0.5;
    const dy = (grid[y+1][x] - grid[y-1][x]) * 0.5;
    fluxSum += Math.sqrt(dx*dx + dy*dy);
    cnt++;
  }
  const meanFluxMagnitude = cnt>0 ? fluxSum/cnt : 0;
  const totalEnergy = sum / N;
  const peakTemp = max;
  return { tempVariance, peakTemp, meanFluxMagnitude, totalEnergy };
};
exports.view = (state, params) => {
  const w = state.w;
  const h = state.h;
  const grid = state.grid;
  const norm = [];
  for (let y=0; y<h; y++) {
    const row = [];
    for (let x=0; x<w; x++) {
      let v = grid[y][x] / 100;
      if (v<0) v=0; if (v>1) v=1;
      row.push(v);
    }
    norm.push(row);
  }
  return { kind: "field", grid: norm, w, h };
};
